-- lovable-cron-fallback-reviewed: Wake on insert; bounded queue retries while work exists, unschedule on drain; hourly reconciliation remains existing care job.
CREATE OR REPLACE FUNCTION public.zalo_queue_has_work() RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM public.zalo_oa_config WHERE id=1 AND auto_send AND status='connected') AND EXISTS(SELECT 1 FROM public.notifications WHERE zalo_status IN ('pending','failed') AND zalo_attempts<3 AND created_at>now()-interval '2 days' AND kind NOT IN ('signal_care','leave_remind','content_remind','order_remind','oq_accepted','att_submitted','att_result','att_changed') AND (zalo_error IS NULL OR zalo_error NOT LIKE 'claimed:%')); $$;
CREATE OR REPLACE FUNCTION public.zalo_queue_tick() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE j bigint; BEGIN IF public.zalo_queue_has_work() THEN PERFORM net.http_post(url:='https://base.suviet.vn/api/public/zalo/dispatch-cron',headers:=jsonb_build_object('Content-Type','application/json','x-care-token',care_cron_token),body:='{}'::jsonb,timeout_milliseconds:=60000) FROM public.zalo_oa_config WHERE id=1 AND care_cron_token IS NOT NULL; ELSE SELECT jobid INTO j FROM cron.job WHERE jobname='zalo-queue-retry'; IF j IS NOT NULL THEN PERFORM cron.unschedule(j); END IF; END IF; END $$;
CREATE OR REPLACE FUNCTION public.zalo_queue_wake() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF NEW.kind IN ('signal_care','leave_remind','content_remind','order_remind','oq_accepted','att_submitted','att_result','att_changed') OR NEW.zalo_status NOT IN ('pending','failed') OR NEW.zalo_attempts>=3 THEN RETURN NEW; END IF; IF NOT EXISTS(SELECT 1 FROM public.zalo_oa_config WHERE id=1 AND auto_send AND status='connected' AND care_cron_token IS NOT NULL) THEN RETURN NEW; END IF; PERFORM pg_advisory_xact_lock(746201); IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='zalo-queue-retry') THEN PERFORM cron.schedule('zalo-queue-retry','* * * * *','SELECT public.zalo_queue_tick();'); END IF; IF TG_OP='INSERT' THEN PERFORM net.http_post(url:='https://base.suviet.vn/api/public/zalo/dispatch-cron',headers:=jsonb_build_object('Content-Type','application/json','x-care-token',care_cron_token),body:='{}'::jsonb,timeout_milliseconds:=60000) FROM public.zalo_oa_config WHERE id=1; END IF; RETURN NEW; EXCEPTION WHEN OTHERS THEN RETURN NEW; END $$;
CREATE TRIGGER zalo_queue_wake AFTER INSERT OR UPDATE OF zalo_status ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.zalo_queue_wake();
REVOKE ALL ON FUNCTION public.zalo_queue_has_work(),public.zalo_queue_tick(),public.zalo_queue_wake() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.zalo_queue_has_work(),public.zalo_queue_tick() TO service_role;